#!/usr/bin/env bash
HOST="`hostname | sed -e 's/\([a-zA-Z0-9\-]*\).*/\1/'`"
USER=`whoami`
HIM=$USER@$HOST
WHEN=`date | \
 awk '{ \
       if (NF==6) \
          { print $1 " "  $2 " "  $3 " "  $6 " at " $4 " " $5 } \
       else \
         { print $1 " "  $2 " "  $3 " "  $7 " at " $4 " " $5 " " $6 }}'`

cat >version.c <<!END!
/**
** @file version.c
** @brief Build-stamped version accessors for ircituilib.
**
** ircituilib -- part of the IRCIT source distribution.
**
** Generated by src/version.c.sh -- do not edit.
**
** The names carry the IrcitUiLib module prefix rather than mirroring ircit's
** c_version/u_compiled/t_compiled: this object is linked into libircitui.a and
** an archive member is pulled exactly when one of its symbols is referenced --
** which is precisely when an unprefixed name would collide with ircit's own
** version object.
**
** The shape is uflib's src/version.c.sh, names included: uflib exposes
** UfsrvUfLibVersion() for the library uflib, so this exposes IrcitUiLibVersion()
** for the library ircituilib. The build stamps are file-static because nothing
** outside this file reports them, the version string is const, and each
** component is reached through an accessor rather than read from a writable
** global. The accessors are declared const in <version.h>.
*/

#include <version.h>

static const char *t_compiled = "$WHEN";
static const char *u_compiled = "$HIM";
const char *ircituilib_version = "IRCITUI " STRINGISE(IRCITUI_MAJOR) "." STRINGISE(IRCITUI_MINOR) "." STRINGISE(IRCITUI_PATCH) "." STRINGISE(IRCITUI_INTERNAL);

const char *IrcitUiLibVersion(void)          { return ircituilib_version; }
const char *IrcitUiLibVersionMajor(void)     { return STRINGISE(IRCITUI_MAJOR); }
const char *IrcitUiLibVersionMinor(void)     { return STRINGISE(IRCITUI_MINOR); }
const char *IrcitUiLibVersionPatch(void)     { return STRINGISE(IRCITUI_PATCH); }
const char *IrcitUiLibVersionInternal(void)  { return STRINGISE(IRCITUI_INTERNAL); }
const char *IrcitUiLibCompiledAt(void)       { return t_compiled; }
const char *IrcitUiLibCompiledBy(void)       { return u_compiled; }

!END!
